on collaborationEvent(item, lifecycleStatus) {
    const toolLabel = typeof item.tool === 'string' && item.tool.length > 0 ? item.tool : 'Agent tool';

    return {
        ...eventBase(item, lifecycleStatus, `Collaboration: ${toolLabel}`),
        content: item.prompt ?? '',
        output: boundedAgentResult(selectedEventContent({
            agentsStates: item.agentsStates,
            receiverThreadIds: item.receiverThreadIds,
        }, false)),
    };
}

function normalizeCodexEvent(item, lifecycleStatus) {
    if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') return null;
    const type = canonicalCodexItemType(item.type);
    if (!SUPPORTED_CODEX_ITEM_TYPES.has(type)) return null;
    const normalizedItem = type === item.type ? item : { ...item, type };
    if (type === 'reasoning') return reasoningEvent(normalizedItem, lifecycleStatus);
    if (type === 'commandExecution') return commandEvent(normalizedItem, lifecycleStatus);
    if (type === 'fileChange') return fileEvent(normalizedItem, lifecycleStatus);
    if (type === 'mcpToolCall') return mcpEvent(normalizedItem, lifecycleStatus);
    if (type === 'dynamicToolCall') return dynamicToolEvent(normalizedItem, lifecycleStatus);
    if (type === 'collabAgentToolCall') return collaborationEvent(normalizedItem, lifecycleStatus);
    if (type === 'webSearch') {
        return {
            ...eventBase(normalizedItem, lifecycleStatus, 'Web search'),
            content: normalizedItem.query,
            output: boundedAgentResult(normalizedContent(normalizedItem.action) ?? ''),
        };
    }
    if (type === 'imageView') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Image view'), content: normalizedItem.path };
    }
    if (type === 'plan') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Plan'), content: normalizedItem.text };
    }
    if (type === 'contextCompaction') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Context compacted') };
    }
    if (type === 'enteredReviewMode' || type === 'exitedReviewMode') {
        const label = type === 'enteredReviewMode' ? 'Entered review mode' : 'Exited review mode';

        return { ...eventBase(normalizedItem, lifecycleStatus, label), content: normalizedItem.review };
    }

    return null;
}

function diagnosticEvent(method, itemType, itemId, sequence) {
    const providerItemId = typeof itemId === 'string' && itemId.length > 0 ? itemId : 'unknown';
    const normalizedType = typeof itemType === 'string' && itemType.length > 0 ? itemType : 'unknown';

    return {
        content: `${method}: ${normalizedType} (${providerItemId})`,
        label: 'Codex protocol diagnostic',
        providerItemId: `diagnostic:${providerItemId}:${sequence}`,
        status: 'completed',
        type: 'diagnostic',
    };
}

function systemEvent(method, params) {
    const turnId = typeof params.turnId === 'string' ? params.turnId : 'unknown-turn';
    const providerItemId = `system:${turnId}:${method}`;
    if (method === 'model/rerouted') {
        return {
            content: `${params.fromModel} to ${params.toModel}: ${optionalContent(params.reason)}`,
            label: 'Model rerouted',
            providerItemId,
            status: 'completed',
            type: 'system',
        };
    }
    if (method === 'model/safetyBuffering/updated') {
        return {
            content: optionalContent({ reasons: params.reasons, useCases: params.useCases }),
            label: 'Safety buffering',
            providerItemId,
            status: params.showBufferingUi ? 'inProgress' : 'completed',
            type: 'system',
        };
    }
    if (method === 'model/verification') {
        return {
            content: optionalContent(params.verifications),
            label: 'Model verification',
            providerItemId,
            status: 'completed',
            type: 'system',
        };
    }

    return null;
}

module.exports = {
    countUnifiedDiffLines,
    diagnosticEvent,
    normalizeCodexEvent,
    systemEvent,
};

const { validateAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
const { normalizeChangedPaths, normalizedContent } = require('./agent_event_utils');

const CLAUDE_FILE_TOOLS = new Set(['Edit', 'MultiEdit', 'NotebookEdit', 'Write']);

/**
 * Claude speaks the same stream-json wire format on both the one-shot and the streaming path, so
 * every decoder here is shared by `agent_provider_protocol` and `ClaudeStreamingAdapter`. Keep it
 * that way: a decoder that lives in only one of them silently gives the two paths different output
 * for identical agent behaviour.
 */
function claudeAssistantText(event) {
    if (event.type !== 'assistant' || !Array.isArray(event.message?.content)) return '';

    return event.message.content
        .filter(({ type }) => type === 'text')
        .map(({ text }) => text)
        .filter((text) => typeof text === 'string')
        .join('');
}

function claudeChangedPaths(event, rootPath) {
    if (event.type !== 'assistant' || !Array.isArray(event.message?.content)) return [];

    const filePaths = event.message.content
        .filter((block) => block?.type === 'tool_use' && CLAUDE_FILE_TOOLS.has(block.name))
        .map(({ input, name }) => name === 'NotebookEdit' ? input?.notebook_path : input?.file_path);

    return normalizeChangedPaths(rootPath, filePaths);
}

/** Tool calls and their results, so the transcript shows what ran as well as what came back. */
function claudeTranscriptEvents(event) {
    if (!Array.isArray(event.message?.content)) return [];
    if (event.type === 'assistant') {
        return event.message.content
            .filter((block) => block?.type === 'tool_use')
            .map((block) => ({ content: JSON.stringify(block.input ?? {}), toolType: `tool.${block.name}` }));
    }
    if (event.type === 'user') {
        return event.message.content
            .filter((block) => block?.type === 'tool_result')
            .map((block) => ({ content: normalizedContent(block.content), toolType: 'tool.result' }))
            .filter(({ content }) => content !== null);
    }

    return [];
}

// Claude folds thinking into output_tokens, so reasoningTokens is always 0, and reports cache
// creation and cache reads as buckets alongside a cache-free input_tokens.
function claudeUsage(event) {
    if (event.type !== 'result' || !event.usage || typeof event.usage !== 'object' || Array.isArray(event.usage)) return null;

    return validateAgentTokenUsage({
        cachedInputTokens: (event.usage.cache_creation_input_tokens ?? 0) + (event.usage.cache_read_input_tokens ?? 0),
        costUsd: event.total_cost_usd,
        inputTokens: event.usage.input_tokens,
        outputTokens: event.usage.output_tokens,
        reasoningTokens: 0,
    }, event.usage.total_tokens);
}

module.exports = { claudeAssistantText, claudeChangedPaths, claudeTranscriptEvents, claudeUsage };

const { validateAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
const { claudeAssistantText, claudeChangedPaths, claudeTranscriptEvents, claudeUsage } = require('./agent_claude_events');
const { codexChangedPaths, codexTranscriptEvents } = require('./agent_codex_events');
const { JsonLineBuffer } = require('./agent_event_utils');

const MISSING_SESSION_CODES = new Set([
    'conversation_not_found',
    'invalid_session_id',
    'resume_session_not_found',
    'session_not_found',
    'thread_not_found',
]);

// Codex exec reports one `turn.completed` per turn whose counters already cover every model request
// in that turn, so this needs no accumulation of its own (the streaming app-server protocol does;
// see `codexTurnCounters`). Cached tokens are a subset of input_tokens and reasoning a subset of
// output_tokens; subtracting here makes the buckets disjoint and inputTokens fresh-only, matching
// how claude reports them.
function codexUsage(event) {
    const usage = event.usage;
    if (event.type !== 'turn.completed' || !usage || typeof usage !== 'object' || Array.isArray(usage)) return null;
    const cachedInputTokens = usage.cached_input_tokens;

    const inputTokens = usage.input_tokens;
    const outputTokens = usage.output_tokens;
    const reasoningTokens = usage.reasoning_output_tokens ?? 0;

    return validateAgentTokenUsage({
        cachedInputTokens: cachedInputTokens ?? 0,
        inputTokens: inputTokens - (cachedInputTokens ?? 0),
        outputTokens: outputTokens - reasoningTokens,
        reasoningTokens,
    }, usage.total_tokens);
}

function providerUsage(agent, event) {
    return agent === 'codex' ? codexUsage(event) : claudeUsage(event);
}

function providerChangedPaths(agent, event, rootPath) {
    if (agent !== 'codex') return claudeChangedPaths(event, rootPath);
    if (event.type !== 'item.completed') return [];

    return codexChangedPaths(event.item, rootPath);
}

function providerTranscriptEvents(agent, event) {
    if (agent !== 'codex') return claudeTranscriptEvents(event);
    if (event.type !== 'item.completed' || !event.item) return [];

    return codexTranscriptEvents(event.item);
}

function eventCodes(event) {
    return [event.code, event.error?.code, event.error?.type, event.result?.code, event.subtype]
        .filter((value) => typeof value === 'string')
        .map((value) => value.toLowerCase());
}

function codexAssistantText(event) {
    if (event.type !== 'item.completed' || event.item?.type !== 'agent_message') return '';

    return typeof event.item.text === 'string' ? event.item.text : '';
}

function nestedErrorMessage(value) {
    if (typeof value === 'string') {
        try {
            return nestedErrorMessage(JSON.parse(value));
        } catch {
            return value;
        }
    }
    if (!value || typeof value !== 'object' || Array.isArray(value)) return '';

    return nestedErrorMessage(value.message ?? value.error ?? value.result);
}

function providerErrorText(agent, event) {
    if (event.type === 'error') return nestedErrorMessage(event.message ?? event.error);
    if (agent === 'codex' && event.type === 'turn.failed') return nestedErrorMessage(event.error);
    if (agent === 'codex' && event.type === 'item.completed' && event.item?.type === 'error') {
        return nestedErrorMessage(event.item.message ?? event.item.error);
    }
    if (agent === 'claude' && event.type === 'result' && event.is_error === true) {
        return nestedErrorMessage(event.error ?? event.result ?? event.message);
    }

    return '';
}

function providerConversationId(agent, event) {
    if (agent === 'codex' && event.type === 'thread.started') return event.thread_id ?? event.thread?.thread_id ?? null;
    if (agent === 'claude' && typeof event.session_id === 'string') return event.session_id;

    return null;
}

function isTurnEvent(agent, event) {
    if (agent === 'codex') return event.type === 'turn.started' || event.type === 'item.started' || event.type === 'item.completed';
    if (agent === 'claude') return event.type === 'assistant' || event.type === 'user';

    return false;
}

function isMissingSession(agent, event, turnStarted) {
    if (turnStarted) return false;
    if (agent !== 'codex' && agent !== 'claude') return false;
    const isFailureEvent = event.type === 'error' || (agent === 'claude' && event.type === 'result' && event.is_error === true);

    return isFailureEvent && eventCodes(event).some((code) => MISSING_SESSION_CODES.has(code));
}

class AgentProviderProtocolParser {
    constructor(agent, onEvent, onMalformed, rootPath) {
        this.agent = agent;
        this.lines = new JsonLineBuffer(agent, (line) => this.parseLine(line));
        this.onEvent = onEvent;
        this.onMalformed = onMalformed;
        this.rootPath = rootPath;
        this.turnStarted = false;
    }

    push(chunk) {
        this.lines.push(chunk);
    }

    finish() {
        this.lines.finish();
    }

    parseLine(line) {
        let event;
        try {
            event = JSON.parse(line);
        } catch {
            this.onMalformed(line);
            return;
        }
        if (!event || typeof event !== 'object' || Array.isArray(event)) {
            this.onMalformed(line);
            return;
        }

        const missingSession = isMissingSession(this.agent, event, this.turnStarted);
        this.turnStarted = this.turnStarted || isTurnEvent(this.agent, event);
        const assistantText = this.agent === 'codex' ? codexAssistantText(event) : claudeAssistantText(event);
        this.onEvent({
            assistantText,
            changedPaths: providerChangedPaths(this.agent, event, this.rootPath),
            conversationId: providerConversationId(this.agent, event),
            errorText: providerErrorText(this.agent, event),
            missingSession,
            transcriptEvents: providerTranscriptEvents(this.agent, event),
            turnStarted: this.turnStarted,
            usage: providerUsage(this.agent, event),
        });
    }
}

function createAgentProviderProtocolParser(agent, onEvent, onMalformed, rootPath) {
    if (agent !== 'codex' && agent !== 'claude') return null;

    return new AgentProviderProtocolParser(agent, onEvent, onMalformed, rootPath);
}

module.exports = { createAgentProviderProtocolParser, isMissingSession };

const { sumAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
const {
    AGENT_CONVERSATION_USAGE_SCHEMA_VERSION,
    boundedAgentResult,
} = require('../../../../shared/agent_conversations.mjs');

function createMessageEntry(id, role, content, timestamp, agent, sequence) {
    return {
        ...(agent ? { agent } : {}),
        content,
        id,
        kind: 'message',
        role,
        ...(Number.isSafeInteger(sequence) ? { sequence } : {}),
        timestamp,
    };
}

function createEventEntry(id, type, content, timestamp, sequence) {
    return {
        content,
        id,
        kind: 'event',
        ...(Number.isSafeInteger(sequence) ? { sequence } : {}),
        timestamp,
        type,
    };
}

function createProviderEventEntry(providerEvent, id, timestamp, sequence) {
    const content = providerEvent.type === 'commandExecution' || providerEvent.type === 'tool.result'
        ? boundedAgentResult(providerEvent.content)
        : providerEvent.content;
    const event = {
        content,
        id,
        kind: 'event',
        label: providerEvent.label,
        providerItemId: providerEvent.providerItemId,
        sequence,
        status: providerEvent.status,
        timestamp,
        type: providerEvent.type,
    };
    if (typeof providerEvent.command === 'string') event.command = providerEvent.command;
    if (Number.isSafeInteger(providerEvent.deletions) && providerEvent.deletions >= 0) event.deletions = providerEvent.deletions;
    if (Array.isArray(providerEvent.details)) event.details = [...providerEvent.details];
    if (Number.isFinite(providerEvent.durationMs)) event.durationMs = providerEvent.durationMs;
    if (Number.isSafeInteger(providerEvent.exitCode)) event.exitCode = providerEvent.exitCode;
    if (Number.isSafeInteger(providerEvent.insertions) && providerEvent.insertions >= 0) event.insertions = providerEvent.insertions;
    if (providerEvent.type !== 'commandExecution' && typeof providerEvent.output === 'string') {
        event.output = boundedAgentResult(providerEvent.output);
    }
    if (Array.isArray(providerEvent.summary)) event.summary = [...providerEvent.summary];
    if (typeof providerEvent.workingDirectory === 'string') event.workingDirectory = providerEvent.workingDirectory;

    return event;
}

function accumulateUsage(current, turn) {
    return sumAgentTokenUsage([current, turn]);
}

/** Updates conversation status and accumulates only completed running periods. */
function transitionConversationStatus(conversation, status, transitionedAt) {
    if (!conversation.timer) {
        conversation.status = status;
        return;
    }

    const wasRunning = conversation.status === 'running';
    const isRunning = status === 'running';
    if (wasRunning === isRunning) {
        conversation.status = status;
        return;
    }
    const transitionedAtMs = Date.parse(transitionedAt);
    if (Number.isNaN(transitionedAtMs)) throw new Error('Invalid agent conversation timer transition timestamp');

    if (isRunning) {
        conversation.timer = { ...conversation.timer, runningStartedAt: transitionedAt };
    } else {
        const runningStartedAtMs = Date.parse(conversation.timer.runningStartedAt);
        if (Number.isNaN(runningStartedAtMs)) throw new Error('Missing agent conversation running start timestamp');
        if (transitionedAtMs < runningStartedAtMs) throw new Error('Agent conversation timer transition precedes running start');
        conversation.timer = {
            elapsedMs: conversation.timer.elapsedMs + transitionedAtMs - runningStartedAtMs,
            runningStartedAt: null,
        };
    }
    conversation.status = status;
}

function createConversation(request, id, startedAt, reference) {
    if (request.conversation) {
        const legacyUsage = request.conversation.usage && request.conversation.usageSchemaVersion === undefined
            ? {
                cachedInputTokens: 0,
                inputTokens: 0,
                legacyTotalTokens: request.conversation.usage.totalTokens,
                outputTokens: 0,
                reasoningTokens: 0,
                totalTokens: request.conversation.usage.totalTokens,
                ...(request.conversation.usage.costUsd !== undefined ? { costUsd: request.conversation.usage.costUsd } : {}),
            }
            : request.conversation.usage;
        const conversation = {
            ...request.conversation,
            completedAt: null,
            entries: [...request.conversation.entries],
            path: reference,
            providerSessions: [...request.conversation.providerSessions],
            ...(legacyUsage ? { usage: legacyUsage } : {}),
            usageSchemaVersion: AGENT_CONVERSATION_USAGE_SCHEMA_VERSION,
        };
        transitionConversationStatus(conversation, 'running', startedAt);

        return conversation;
    }

    return {
        actionId: request.actionId ?? null,
        cardInternalId: request.activityOrigin.kind === 'card' ? request.activityOrigin.cardInternalId : null,
        cardPath: request.cardPath ?? null,
        completedAt: null,
        entries: [],
        hasExplicitTitle: true,
        id,
        path: reference,
        providerSessions: [],
        startedAt,
        status: 'running',
        timer: { elapsedMs: 0, runningStartedAt: startedAt },
        title: typeof request.title === 'string' && request.title.length > 0 ? request.title : 'Agent run',
        usageSchemaVersion: AGENT_CONVERSATION_USAGE_SCHEMA_VERSION,
        viewed: true,
    };
}

/** Snapshots the mutable conversation collections while reusing immutable entries. */
function snapshotConversation(conversation) {
    return {
        ...conversation,
        entries: [...conversation.entries],
        providerSessions: [...conversation.providerSessions],
    };
}

function updateProviderSession(run, synchronizedThroughMessageId, completedAt) {
    const conversationId = run.providerConversationId ?? run.request.providerConversationId;
    if (!conversationId) return;

    const sessions = run.conversation.providerSessions;
    const current = sessions.find(({ agent }) => agent === run.agent);
    const nextSession = {
        agent: run.agent,
        conversationId,
        createdAt: current?.createdAt ?? completedAt,
        lastUsedAt: completedAt,
        synchronizedThroughMessageId,
    };
    run.conversation.providerSessions = current
        ? sessions.map((session) => (session.agent === run.agent ? nextSession : session))
        : [...sessions, nextSession];
}

module.exports = {
    accumulateUsage,
    createProviderEventEntry,
    createConversation,
    createEventEntry,
    createMessageEntry,
    snapshotConversation,
    transitionConversationStatus,
    updateProviderSession,
};

import type { AgentConversation, AgentTokenUsage, ProjectSnapshot } from '../../data/data_types'
import { sumAgentTokenUsage } from '../../../../shared/agent_usage_math.mjs'
import type { AgentTokenUsageSummary } from '../../../../shared/agent_token_usage_summary.mjs'

export { sumAgentTokenUsage }

export interface AgentUsageVersion {
    name: string
    usage: AgentTokenUsage
}

export interface AgentFileChangeUsage {
    deletions: number
    insertions: number
}

export interface ProjectAgentUsage {
    archived: AgentUsageVersion
    current: AgentUsageVersion
    project: AgentTokenUsage
    releases: AgentUsageVersion[]
}

export function cardAgentTokenUsage(source: AgentConversation[] | ProjectSnapshot['activeCards'][number]): AgentTokenUsage {
    const conversations = Array.isArray(source) ? source : source.agentConversations

    return sumAgentTokenUsage(conversations.map(({ usage }) => usage))
}

/** Aggregate loaded conversations belonging to one action on one card. */
export function actionCardAgentTokenUsage(conversations: AgentConversation[], actionId: string, cardInternalId: string): AgentTokenUsage {
    const matchingUsage = conversations
        .filter((conversation) => conversation.actionId === actionId && conversation.cardInternalId === cardInternalId)
        .map(({ usage }) => usage)

    return sumAgentTokenUsage(matchingUsage)
}

/** Sum completed provider patches in one canonical conversation. */
export function conversationFileChangeUsage(conversation: AgentConversation | null): AgentFileChangeUsage | null {
    if (!conversation) return null
    let countedEvents = 0
    let deletions = 0
    let insertions = 0
    for (const entry of conversation.entries) {
        if (entry.kind !== 'event' || entry.type !== 'fileChange' || entry.status !== 'completed') continue
        const { deletions: eventDeletions, insertions: eventInsertions } = entry
        if (typeof eventDeletions !== 'number' || !Number.isSafeInteger(eventDeletions) || eventDeletions < 0) continue
        if (typeof eventInsertions !== 'number' || !Number.isSafeInteger(eventInsertions) || eventInsertions < 0) continue

        countedEvents += 1
        deletions += eventDeletions
        insertions += eventInsertions
    }

    return countedEvents > 0 ? { deletions, insertions } : null
}

function isInsideFolder(cardPath: string, folder: string) {
    const normalizedFolder = folder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const normalizedCardPath = cardPath.replace(/\\/gu, '/')

    return normalizedCardPath.startsWith(`${normalizedFolder}/`)
}

/** Use persisted project/release totals while deriving current and archived detail from loaded activity. */
export function projectAgentTokenUsage(
    snapshot: ProjectSnapshot | null,
    archivedFolder: string,
    summary: AgentTokenUsageSummary,
): ProjectAgentUsage {
    const activeCards = snapshot?.activeCards ?? []
    const backgroundCards = snapshot?.backgroundCards ?? []
    const currentUsage = sumAgentTokenUsage(activeCards.map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)))
    const archivedUsage = sumAgentTokenUsage(
        backgroundCards
            .filter((card) => isInsideFolder(card.path, archivedFolder))
            .map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)),
    )
    const releases = Object.entries(summary.releases)
        .map(([name, usage]) => ({ name, usage }))
        .sort((left, right) => left.name.localeCompare(right.name))

    return {
        archived: { name: 'Archived', usage: archivedUsage },
        current: { name: 'Current', usage: currentUsage },
        project: summary.projectUsage,
        releases,
    }
}

import type { AgentConversation, AgentTokenUsage } from '../../../../data/data_types'
import type { ActionRunHistoryEntry, CommitReference } from '../../../../data/electron_action_bridge'
import {
    conversationFileChangeUsage,
    sumAgentTokenUsage,
    type AgentFileChangeUsage,
} from '../../../../services/agents/agent_usage'

export interface LineUsage {
    commits: CommitReference[]
    deletions: number
    filesChanged: number
    insertions: number
}

export interface ActionUsageValues {
    changes: AgentFileChangeUsage | null
    lines: LineUsage
    tokens: AgentTokenUsage
}

export interface ScopedActionUsage {
    actionCard: ActionUsageValues
    conversation: ActionUsageValues | null
}

function conversationsForActionCard(
    conversations: AgentConversation[],
    liveConversation: AgentConversation | null,
    actionId: string,
    cardInternalId: string,
) {
    const conversationsById = new Map<string, AgentConversation>()
    for (const conversation of conversations) {
        if (conversation.actionId !== actionId || conversation.cardInternalId !== cardInternalId) continue

        conversationsById.set(conversation.id, conversation)
    }
    if (liveConversation?.actionId === actionId && liveConversation.cardInternalId === cardInternalId) {
        conversationsById.set(liveConversation.id, liveConversation)
    }

    return [...conversationsById.values()]
}

/** Sums reported patches; `null` when no conversation in scope reported any file change. */
function fileChangeUsage(conversations: AgentConversation[]) {
    return conversations.reduce<AgentFileChangeUsage | null>((total, conversation) => {
        const usage = conversationFileChangeUsage(conversation)
        if (!usage) return total
        if (!total) return { deletions: usage.deletions, insertions: usage.insertions }

        return { deletions: total.deletions + usage.deletions, insertions: total.insertions + usage.insertions }
    }, null)
}

function lineUsage(history: ActionRunHistoryEntry[]): LineUsage {
    const commits = history.flatMap((entry) => entry.commits ?? [])

    return commits.reduce((totals, commit) => ({
        commits: totals.commits,
        deletions: totals.deletions + commit.deletions,
        filesChanged: totals.filesChanged + commit.filesChanged,
        insertions: totals.insertions + commit.insertions,
    }), { commits, deletions: 0, filesChanged: 0, insertions: 0 })
}

function usageValues(conversations: AgentConversation[], history: ActionRunHistoryEntry[]): ActionUsageValues {
    return {
        changes: fileChangeUsage(conversations),
        lines: lineUsage(history),
        tokens: sumAgentTokenUsage(conversations.map(({ usage }) => usage)),
    }
}

/** Aggregates every usage metric for conversation and action/card scopes. */
export function scopedActionUsage(
    conversations: AgentConversation[],
    liveConversation: AgentConversation | null,
    displayedConversation: AgentConversation | null,
    history: ActionRunHistoryEntry[],
    actionId: string,
    cardInternalId: string,
): ScopedActionUsage {
    const actionCardConversations = conversationsForActionCard(
        conversations,
        liveConversation,
        actionId,
        cardInternalId,
    )
    const actionCard = usageValues(actionCardConversations, history)
    if (!displayedConversation) return { actionCard, conversation: null }

    const conversationHistory = history.filter((entry) => (
        entry.type === 'agent' && entry.rootConversationId === displayedConversation.id
    ))

    return {
        actionCard,
        conversation: usageValues([displayedConversation], conversationHistory),
    }
}

